    contextEn: "One of the most celebrated love poems of the Umayyad era, containing the immortal verse \"Indeed the eyes whose glance holds languor,\" reckoned among the tenderest the Arabs ever uttered on the bewitching power of a glance. It opens with the departure and farewell of loved ones, then turns to a lover's complaint of glances that fell him though they are the frailest of created things.",
