    contextEn: "Al-Mutanabbi composed this in praise of Sayf al-Dawla al-Hamdani, celebrating his recapture of the fortress of al-Hadath from the Byzantines in 954 CE. It stands among the most famous odes of pride and martial valor, opening with a proverbial line of wisdom: that resolves rise in measure with the resolute, and noble deeds with the noble.",
