    contextEn: "This is the opening of the first (Sanaa) maqama of al-Hariri's Maqamat, in which the narrator al-Harith ibn Hammam begins his tale by describing his exile and destitution upon entering Sanaa, setting the stage for his encounter with the cycle's trickster hero, Abu Zayd al-Saruji.",
