    contextAr: "هذا المقطع هو مطلع «التوطئة» التي افتتح بها جبران مجموعته النثرية «دمعة وابتسامة» (نُشرت 1914)، وهي من أشهر فقراته إذ يلخّص فيها فلسفته في احتضان الحزن والفرح معًا كجوهر للحياة.",
    contextEn: "This passage opens the preamble (tawti'a) of Gibran's prose collection A Tear and a Smile (published 1914). It is among his most celebrated paragraphs, distilling his philosophy of embracing both sorrow and joy as the essence of life.",
