      "سَتَبكي شَجوَها فَرَسي وَمُهري صَفائِحُ دَمعُها ماءُ الجُسومِ",
      "قَرَبنَ النارَ ثُمَّ نَشَأنَ فيها كَما نَشَأَ العَذارى في النَعيمِ",
