      "جَحَدتُها وَكَتَمتُ السَهمَ في كَبِدي جُرحُ الأَحِبَّةِ عِندي غَيرُ ذي أَلَمِ",
      "رُزِقتَ أَسمَحَ ما في الناسِ مِن خُلُقٍ إِذا رُزِقتَ التِماسَ العُذرِ في الشِيَمِ",
